import { z } from 'zod';

const bool = z.enum(['true', 'false', '1', '0']).transform((v) => v === 'true' || v === '1');

const base64Key32 = z.string().refine((v) => Buffer.from(v, 'base64').length === 32, {
  message: 'must be 32 random bytes, base64-encoded (Render "generateValue" produces exactly this)',
});

/**
 * Environment contract. On Render:
 *  - PORT and RENDER_EXTERNAL_URL are provided by the platform;
 *  - ENCRYPTION_KEY, SESSION_SECRET, ADMIN_SETUP_TOKEN are generated by render.yaml (generateValue);
 *  - FIREBASE_SERVICE_ACCOUNT is the only value the owner pastes.
 */
export const envSchema = z
  .object({
    NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),
    PORT: z.coerce.number().int().min(1).max(65535).default(8080),
    HOST: z.string().default('0.0.0.0'),
    LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('info'),

    STORAGE_DRIVER: z.enum(['local', 'firestore']).optional(),
    LOCAL_DATA_FILE: z.string().default('.data/local-store.json'),
    /** Full service-account key: raw JSON or base64 of it. */
    FIREBASE_SERVICE_ACCOUNT: z.string().optional(),

    ENCRYPTION_KEY: base64Key32,
    ENCRYPTION_KEY_ID: z.string().regex(/^[a-z0-9]{1,16}$/i).default('k1'),
    ENCRYPTION_KEY_PREVIOUS: z.string().regex(/^[a-z0-9]{1,16}:.+$/i).optional(),

    SESSION_SECRET: z.string().min(32, 'must be at least 32 characters'),
    SESSION_TTL_SEC: z.coerce.number().int().min(300).max(7 * 86400).default(12 * 3600),
    ADMIN_SESSION_TTL_SEC: z.coerce.number().int().min(900).max(30 * 86400).default(7 * 86400),
    INIT_DATA_MAX_AGE_SEC: z.coerce.number().int().min(60).max(7 * 86400).default(86400),
    /** One-time secret required to create the first owner account. */
    ADMIN_SETUP_TOKEN: z.string().min(24, 'must be at least 24 characters').optional(),

    PUBLIC_URL: z.string().url().optional(),
    RENDER_EXTERNAL_URL: z.string().url().optional(),
    /** Extra origins allowed to call the API (only needed when UIs are served from another origin). */
    CORS_ORIGINS: z.string().default(''),
    TRUST_PROXY: bool.optional(),
    TELEGRAM_API_BASE: z.string().url().default('https://api.telegram.org'),
    WEB_DIST_DIR: z.string().optional(),
  })
  .transform((env) => ({
    ...env,
    STORAGE_DRIVER: env.STORAGE_DRIVER ?? (env.NODE_ENV === 'production' ? 'firestore' : 'local'),
    TRUST_PROXY: env.TRUST_PROXY ?? env.NODE_ENV === 'production',
    PUBLIC_URL: (env.PUBLIC_URL ?? env.RENDER_EXTERNAL_URL ?? `http://localhost:${env.PORT}`).replace(/\/$/, ''),
    PUBLIC_URL_EXPLICIT: Boolean(env.PUBLIC_URL ?? env.RENDER_EXTERNAL_URL),
  }))
  .superRefine((env, ctx) => {
    if (env.NODE_ENV === 'production') {
      if (env.STORAGE_DRIVER !== 'firestore') {
        ctx.addIssue({ code: 'custom', path: ['STORAGE_DRIVER'], message: 'production requires firestore (the server disk is not persistent)' });
      }
      if (!env.PUBLIC_URL_EXPLICIT || !env.PUBLIC_URL.startsWith('https://')) {
        ctx.addIssue({ code: 'custom', path: ['PUBLIC_URL'], message: 'production requires an https public URL (Render sets RENDER_EXTERNAL_URL automatically)' });
      }
      if (!env.ADMIN_SETUP_TOKEN) ctx.addIssue({ code: 'custom', path: ['ADMIN_SETUP_TOKEN'], message: 'required in production' });
    }
    if (env.STORAGE_DRIVER === 'firestore' && !env.FIREBASE_SERVICE_ACCOUNT) {
      ctx.addIssue({ code: 'custom', path: ['FIREBASE_SERVICE_ACCOUNT'], message: 'required: paste the Firebase service account key (JSON)' });
    }
  });

export type Env = z.infer<typeof envSchema>;

/** Validates process env. Errors list variable names only, never values. */
export function loadEnv(source: Record<string, string | undefined> = process.env): Env {
  const parsed = envSchema.safeParse(source);
  if (!parsed.success) {
    const lines = parsed.error.issues.map((i) => `  - ${i.path.join('.') || '(root)'}: ${i.message}`);
    throw new Error(`Invalid environment configuration:\n${lines.join('\n')}`);
  }
  return parsed.data;
}

export function corsOrigins(env: Env): string[] {
  return env.CORS_ORIGINS.split(',').map((s) => s.trim()).filter(Boolean);
}

export function miniAppUrl(env: Env, botId: string): string {
  return `${env.PUBLIC_URL}/app/?bot=${encodeURIComponent(botId)}`;
}

export function webhookUrl(env: Env, botId: string): string {
  return `${env.PUBLIC_URL}/tg/webhook/${encodeURIComponent(botId)}`;
}
